        a.accept("item.bettacraft.green_gold_cory_spawn_egg", "Green Gold Cory Spawn Egg");
        a.accept("info.bettacraft.tankmate.green_gold_cory", "Green Gold Cory (Corydoras melanotaenia) from the Rio Meta region in Colombia.\nGold-green with a dark side stripe and yellow-orange fins.\nShoal of 6 or more, 22–27 °C, water: sensitive. Counts 0.55 fish in the stocking.\nGlues its eggs to the glass (after a cool water change).\nCatch: aquarium net in rivers, jungle water, wandering trader.");
        a.accept("entity.bettacraft.leopard_frog_pleco", "L134 Leopard Frog Pleco");
