        a.accept("item.bettacraft.leopard_frog_pleco_spawn_egg", "L134 Leopard Frog Pleco Spawn Egg");
        a.accept("info.bettacraft.tankmate.leopard_frog_pleco", "L134 Leopard Frog Pleco (Peckoltia compta (L134)) from the Rio Tapajós in Brazil.\nA small pleco with yellow and black bands. Lives in caves and on the glass, eats algae a little and needs warm water.\nFine on its own, 25–30 °C, water: sensitive. Counts 1 fish in the stocking.\nSpawns in a cave, the male guards.\nCatch: aquarium net in jungle water, wandering trader.");
        a.accept("entity.bettacraft.zebra_pleco", "L046 Zebra Pleco");
        a.accept("item.bettacraft.zebra_pleco_bucket", "Bucket of L046 Zebra Pleco");
        a.accept("item.bettacraft.zebra_pleco_spawn_egg", "L046 Zebra Pleco Spawn Egg");
        a.accept("info.bettacraft.tankmate.zebra_pleco", "L046 Zebra Pleco (Hypancistrus zebra (L046)) from the rocky rapids of the Rio Xingu in Brazil (protected in the wild).\nBlack and white stripes, very warm, clean water and a cave. Eats meaty food, not algae.\nFine on its own, 26–31 °C, water: very sensitive. Counts 0.9 fish in the stocking.\nSpawns in a cave, the male guards.\nCatch: aquarium net in jungle water, wandering trader.");
